"""Torch port of the at-fault-collision (NC) and time-to-collision (TTC) metrics.

Geometry is convex-quad SAT instead of shapely's STRtree: ego footprints and
T4 track boxes are oriented rectangles, and SAT with inclusive bounds matches
``intersects`` (touching counts) up to fp boundary cases.

Sequencing is the subtle part.  The CPU loops time forward and *excludes* a
track for a proposal after its first not-at-fault contact, so classification
happens at the first qualifying contact only:

* NC: red-light tokens never qualify; every other (proposal, track) pair is
  classified at its first intersecting timestep -- if that contact is not at
  fault the pair never scores, and if it is, later contacts cannot change the
  outcome (min() with the same penalty).
* TTC: contacts at timesteps where ego is slower than the *config* threshold
  (5e-3, not get_collision_type's 5e-2) are skipped WITHOUT excluding the
  track, so the deciding contact is the first one in (time, projection-step)
  lexicographic order whose ego speed passes.

Red lights therefore never enter these tensors at all; the track snapshot
quirks are kept: ``is_track_stopped`` and the penalty class read the unique
per-token snapshot (first appearance), not the per-timestep state.
"""

from __future__ import annotations

import math
from dataclasses import dataclass

import torch


@dataclass
class TrackTensors:
    """Per-window track set for the collision metrics (red lights excluded).

    corners: [T_obs, A, 4, 2] oriented-box corners per observation timestep
    valid:   [T_obs, A] track exists at that timestep
    is_agent_instance: [A] nuPlan ``Agent`` (has velocity) vs static object
    velocity: [A] unique-snapshot speed magnitude
    is_agent_type: [A] tracked_object_type in AGENT_TYPES (0.0 vs 0.5 penalty)
    """

    corners: torch.Tensor
    valid: torch.Tensor
    is_agent_instance: torch.Tensor
    velocity: torch.Tensor
    is_agent_type: torch.Tensor
    # [A, 4] = (min_x, min_y, max_x, max_y) over the track's valid frames;
    # SAT intersection implies bbox overlap, so tracks whose bbox misses the
    # ego's (TTC-extended) reach bbox are droppable with no effect.
    bboxes: torch.Tensor | None = None

    def restricted_to(self, keep: torch.Tensor) -> "TrackTensors":
        kept = keep.nonzero(as_tuple=False).squeeze(-1)
        return TrackTensors(
            corners=self.corners[:, kept],
            valid=self.valid[:, kept],
            is_agent_instance=self.is_agent_instance[kept],
            velocity=self.velocity[kept],
            is_agent_type=self.is_agent_type[kept],
            bboxes=None if self.bboxes is None else self.bboxes[kept],
        )


def _project(corners: torch.Tensor, axes: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
    # corners [..., 4, 2], axes [..., K, 2] -> min/max [..., K]
    scalar = torch.einsum("...cx,...kx->...kc", corners, axes)
    return scalar.amin(dim=-1), scalar.amax(dim=-1)


def quads_intersect(
    quad_a: torch.Tensor,  # [..., 4, 2]
    quad_b: torch.Tensor,  # [..., 4, 2]
) -> torch.Tensor:  # [...] bool
    """Convex-quad SAT with inclusive overlap (touching == intersecting)."""

    def _axes(quad: torch.Tensor) -> torch.Tensor:
        edges = torch.roll(quad, shifts=-1, dims=-2) - quad  # [..., 4, 2]
        normals = torch.stack([-edges[..., 1], edges[..., 0]], dim=-1)
        return normals

    shape = torch.broadcast_shapes(quad_a.shape, quad_b.shape)
    quad_a = quad_a.expand(shape)
    quad_b = quad_b.expand(shape)
    axes = torch.cat([_axes(quad_a), _axes(quad_b)], dim=-2)  # [..., 8, 2]
    min_a, max_a = _project(quad_a, axes)
    min_b, max_b = _project(quad_b, axes)
    separated = (max_a < min_b) | (max_b < min_a)
    return ~separated.any(dim=-1)


def _segments_intersect(
    p1: torch.Tensor, p2: torch.Tensor, q1: torch.Tensor, q2: torch.Tensor
) -> torch.Tensor:
    """Inclusive 2-D segment intersection over broadcast batches [..., 2]."""

    def _orient(a, b, c):
        return (b[..., 0] - a[..., 0]) * (c[..., 1] - a[..., 1]) - (
            b[..., 1] - a[..., 1]
        ) * (c[..., 0] - a[..., 0])

    d1 = _orient(q1, q2, p1)
    d2 = _orient(q1, q2, p2)
    d3 = _orient(p1, p2, q1)
    d4 = _orient(p1, p2, q2)
    proper = ((d1 > 0) != (d2 > 0)) & ((d3 > 0) != (d4 > 0)) & (d1 != d2) & (d3 != d4)

    def _on_segment(a, b, c, cross):
        within = (
            (c[..., 0] <= torch.maximum(a[..., 0], b[..., 0]))
            & (c[..., 0] >= torch.minimum(a[..., 0], b[..., 0]))
            & (c[..., 1] <= torch.maximum(a[..., 1], b[..., 1]))
            & (c[..., 1] >= torch.minimum(a[..., 1], b[..., 1]))
        )
        return (cross == 0) & within

    touching = (
        _on_segment(q1, q2, p1, d1)
        | _on_segment(q1, q2, p2, d2)
        | _on_segment(p1, p2, q1, d3)
        | _on_segment(p1, p2, q2, d4)
    )
    return proper | touching


def segment_intersects_quad(
    seg_start: torch.Tensor,  # [..., 2]
    seg_end: torch.Tensor,  # [..., 2]
    quad: torch.Tensor,  # [..., 4, 2]
) -> torch.Tensor:
    """shapely ``LineString.intersects(Polygon)``: edge crossing or containment."""

    edge_start = quad
    edge_end = torch.roll(quad, shifts=-1, dims=-2)
    crosses = _segments_intersect(
        seg_start[..., None, :], seg_end[..., None, :], edge_start, edge_end
    ).any(dim=-1)

    # Fully-inside segments cross no edge; test one endpoint by parity.
    px, py = seg_start[..., 0][..., None], seg_start[..., 1][..., None]
    ax, ay = edge_start[..., 0], edge_start[..., 1]
    bx, by = edge_end[..., 0], edge_end[..., 1]
    straddles = (ay > py) != (by > py)
    denominator = torch.where(straddles, by - ay, torch.ones_like(by))
    crossing_x = ax + (py - ay) * (bx - ax) / denominator
    inside = ((straddles & (px < crossing_x)).sum(dim=-1) % 2) == 1
    return crosses | inside


def _relative_angle(
    ego_xy: torch.Tensor,  # [..., 2]
    ego_heading: torch.Tensor,  # [...]
    agent_xy: torch.Tensor,  # [..., 2]
) -> torch.Tensor:
    """``get_agent_relative_angle``: arccos of heading-vs-offset alignment."""

    offset = agent_xy - ego_xy
    norm = torch.linalg.vector_norm(offset, dim=-1)
    direction = offset / norm.clamp(min=1e-300)[..., None]
    dot = (
        torch.cos(ego_heading) * direction[..., 0]
        + torch.sin(ego_heading) * direction[..., 1]
    )
    return torch.arccos(dot)


_AHEAD_RAD = math.radians(30.0)
_BEHIND_RAD = math.radians(150.0)


def no_at_fault_collision_torch(
    ego_corners: torch.Tensor,  # [N, T, 4, 2] FL/RL/RR/FR
    ego_states: torch.Tensor,  # [N, T, 11]
    ego_area_fault: torch.Tensor,  # [N, T] multiple-lanes OR non-drivable
    tracks: TrackTensors,
    stopped_speed_threshold: float = 5e-2,
) -> torch.Tensor:  # [N] NC score in {1.0, 0.5, 0.0}
    from t4_e2e_devkit.planning.simulation.planner.pdm_planner.utils.pdm_enums import StateIndex

    n_proposals, n_time = ego_corners.shape[:2]
    track_quads = tracks.corners[:n_time]  # [T, A, 4, 2]
    track_valid = tracks.valid[:n_time]

    hits = quads_intersect(
        ego_corners[:, :, None], track_quads[None]
    ) & track_valid[None]  # [N, T, A]

    any_hit = hits.any(dim=1)  # [N, A]
    time_index = torch.arange(n_time, device=hits.device)[None, :, None]
    first_t = (
        torch.where(hits, time_index, torch.full_like(time_index, n_time))
        .amin(dim=1)
        .clamp(max=n_time - 1)
    )  # [N, A]; guaranteed-first, sentinel clamped for the no-hit rows

    rows = torch.arange(n_proposals, device=hits.device)[:, None]
    ego_at_hit = ego_states[rows, first_t]  # [N, A, 11]
    ego_speed = torch.hypot(
        ego_at_hit[..., StateIndex.VELOCITY_X], ego_at_hit[..., StateIndex.VELOCITY_Y]
    )
    ego_stopped = ego_speed <= stopped_speed_threshold

    track_stopped = (~tracks.is_agent_instance) | (
        tracks.velocity <= stopped_speed_threshold
    )  # [A]

    track_at_hit = track_quads[first_t, torch.arange(track_quads.shape[1])[None, :]]
    centroid = track_at_hit.mean(dim=-2)  # rectangle centroid == corner mean
    angle = _relative_angle(
        ego_at_hit[..., :2], ego_at_hit[..., StateIndex.HEADING], centroid
    )
    behind = angle > _BEHIND_RAD

    ego_at_hit_corners = ego_corners[rows, first_t]  # [N, A, 4, 2]
    front_hit = segment_intersects_quad(
        ego_at_hit_corners[..., 0, :], ego_at_hit_corners[..., 3, :], track_at_hit
    )

    fault_area = ego_area_fault[rows, first_t]  # [N, A]

    at_fault = (~ego_stopped) & (
        track_stopped[None]
        | ((~behind) & front_hit)
        | ((~behind) & (~front_hit) & fault_area)
    )
    at_fault = at_fault & any_hit

    if tracks.corners.shape[1] == 0:
        return torch.ones(n_proposals, dtype=ego_states.dtype, device=hits.device)
    penalty = torch.where(
        tracks.is_agent_type[None], torch.zeros_like(ego_speed), torch.full_like(ego_speed, 0.5)
    )
    scores = torch.where(at_fault, penalty, torch.ones_like(penalty))
    return scores.amin(dim=-1)


def ttc_torch(
    ego_corners: torch.Tensor,  # [N, T, 4, 2]
    ego_states: torch.Tensor,  # [N, T, 11]
    ego_area_fault: torch.Tensor,  # [N, T]
    rear_axle_in_intersection: torch.Tensor,  # [N, T]
    tracks: TrackTensors,
    interval_length: float,
    stopped_speed_threshold: float = 5e-3,
) -> torch.Tensor:  # [N] TTC score in {1.0, 0.0}
    from t4_e2e_devkit.planning.simulation.planner.pdm_planner.utils.pdm_enums import StateIndex

    n_proposals, n_time = ego_corners.shape[:2]
    future_steps = torch.arange(0, 10, 3, device=ego_corners.device)  # 0,3,6,9
    n_steps = future_steps.shape[0]

    speeds = torch.hypot(
        ego_states[..., StateIndex.VELOCITY_X], ego_states[..., StateIndex.VELOCITY_Y]
    )  # [N, T]
    direction = torch.stack(
        [
            torch.cos(ego_states[..., StateIndex.HEADING]) * speeds,
            torch.sin(ego_states[..., StateIndex.HEADING]) * speeds,
        ],
        dim=-1,
    )  # [N, T, 2]

    delta_t = future_steps.to(ego_corners.dtype) * interval_length  # [S]
    projected = (
        ego_corners[:, :, None]
        + (direction[:, :, None, :] * delta_t[None, None, :, None])[..., None, :]
    )  # [N, T, S, 4, 2]

    obs_index = torch.arange(n_time, device=ego_corners.device)[:, None] + future_steps[None]
    # [T, S] observation timestep per pair
    track_quads = tracks.corners[obs_index]  # [T, S, A, 4, 2]
    track_valid = tracks.valid[obs_index]  # [T, S, A]

    hits = quads_intersect(
        projected[:, :, :, None], track_quads[None]
    ) & track_valid[None]  # [N, T, S, A]

    # The deciding pair: first (t, s) lexicographically whose ego speed at t
    # passes the config threshold.
    speed_ok = speeds >= stopped_speed_threshold  # [N, T]
    qualifying = hits & speed_ok[:, :, None, None]
    flat = qualifying.reshape(n_proposals, n_time * n_steps, -1)  # [N, TS, A]
    any_hit = flat.any(dim=1)
    pair_index = torch.arange(n_time * n_steps, device=hits.device)[None, :, None]
    first_pair = (
        torch.where(flat, pair_index, torch.full_like(pair_index, n_time * n_steps))
        .amin(dim=1)
        .clamp(max=n_time * n_steps - 1)
    )  # [N, A]; lexicographic-first by construction
    first_t = first_pair // n_steps
    first_s = first_pair % n_steps

    rows = torch.arange(n_proposals, device=hits.device)[:, None]
    cols = torch.arange(flat.shape[-1], device=hits.device)[None, :]
    ego_at = ego_states[rows, first_t]  # [N, A, 11]

    track_at = track_quads[first_t, first_s, cols]  # [N, A, 4, 2]
    centroid = track_at.mean(dim=-2)
    angle = _relative_angle(ego_at[..., :2], ego_at[..., StateIndex.HEADING], centroid)
    ahead = angle < _AHEAD_RAD
    behind = angle > _BEHIND_RAD

    area_fault = ego_area_fault[rows, first_t] | rear_axle_in_intersection[rows, first_t]
    triggers = ahead | (area_fault & (~behind))
    triggers = triggers & any_hit

    return torch.where(
        triggers.any(dim=-1),
        torch.zeros((), dtype=torch.float64, device=hits.device),
        torch.ones((), dtype=torch.float64, device=hits.device),
    )
